"""ORD_LINE renumbering migration."""

from decimal import Decimal
from typing import Any


def _line_number(value: Any) -> Decimal:
    """Return a numeric sorting value, treating a missing/blank value as zero."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and renumber surviving lines per order."""
    surviving = [
        (index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            str(item[1].get("ORD_ID", "")),
            _line_number(item[1].get("LINE_NO", "")),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    new_line_number = 0

    for _, row in surviving:
        order = str(row.get("ORD_ID", ""))
        if order != current_order:
            current_order = order
            new_line_number = 1
        else:
            new_line_number += 1

        copied_row = dict(row)
        copied_row["LINE_NO"] = new_line_number
        result.append(copied_row)

    return result
